        if (imageEffectThresholdSoftnessValue && imageEffectThresholdSoftness)
          imageEffectThresholdSoftnessValue.value = imageEffectThresholdSoftness.value + "%";
        if (imageEffectPosterizeLevelsValue && imageEffectPosterizeLevels)
          imageEffectPosterizeLevelsValue.value = imageEffectPosterizeLevels.value + "%";
        if (imageEffectPosterizeDitherValue && imageEffectPosterizeDither)
          imageEffectPosterizeDitherValue.value = imageEffectPosterizeDither.value + "%";
        if (imageEffectDuotoneBalanceValue && imageEffectDuotoneBalance)
          imageEffectDuotoneBalanceValue.value = imageEffectDuotoneBalance.value + "%";
