        var start = rightSide
          ? curveControls.sourceRight
          : curveControls.sourceLeft;
        var end = rightSide
          ? curveControls.targetRight
          : curveControls.targetLeft;
        if (!start || !end) return null;
        var amount = clamp(targetT, 0, 1);
