          left: left,
          right: right,
          center: center,
          tangent: tangent,
          inward: inward,
          outward: outward,
          exit: exit,
          leftExit: leftExit,
          rightExit: rightExit,
          endCenter: endCenter,
          nearBase: nearBase,
          nearLeft: nearLeft,
          nearRight: nearRight,
