        var leftTrim = quadraticPointAt(leftPoint, leftControl, tip, 1 - trim);
        var rightTrim = quadraticPointAt(tip, rightControl, rightPoint, trim);
        var capControl = getRoundedTailCapControl(leftTrim, tip, rightTrim, roundness);
        c.quadraticCurveTo(leftControl.x, leftControl.y, leftTrim.x, leftTrim.y);
        c.quadraticCurveTo(capControl.x, capControl.y, rightTrim.x, rightTrim.y);
