        var tilesY = Math.max(1, Math.ceil(targetH / tileSize));

        var startX = Math.max(0, Math.floor(damagePx.x / tileSize));
        var startY = Math.max(0, Math.floor(damagePx.y / tileSize));
        var endX = Math.min(
          tilesX - 1,
          Math.floor((damagePx.x + damagePx.w - 1) / tileSize)
        );
        var endY = Math.min(
          tilesY - 1,
          Math.floor((damagePx.y + damagePx.h - 1) / tileSize)
        );

